using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renamed the discriminator property
        // from "Discriminator" to "$type". Existing documents still use the
        // old name, so we must preserve it explicitly.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 no longer prepends the discriminator
        // to the "id" property (was "Blog|1", now just "1"). Existing
        // documents use the old format, so opt back in to the legacy behavior.
        modelBuilder.Entity<Blog>().HasPartitionKey(e => e.Id);
        modelBuilder.Entity<Blog>().Property(e => e.Id)
            .HasJsonPropertyName("id");
        modelBuilder.Entity<Blog>().ToContainer("Blogs")
            .HasNoDiscriminatorInJsonId(false);

        // Breaking change 3: HasIndex() now throws for Cosmos DB.
        // Cosmos indexes are managed via indexing policy, not EF.
        // REMOVED: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

